import { sql, type AnyColumn, type SQL } from "drizzle-orm";
import { customType, timestamp, uuid } from "drizzle-orm/pg-core";

/** UUIDv7 primary key, generated by Postgres 18's native `uuidv7()` (time-sortable). */
export const idColumn = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);

export const timestamps = () => ({
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  // Drizzle sets this on every ORM update; raw SQL updates must set it themselves.
  updatedAt: timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/** Case-insensitive text (the `citext` extension is created in migration 0000). Used for emails. */
export const citext = customType<{ data: string }>({
  dataType: () => "citext",
});

// Values come from our own const tuples, never from users; the pattern keeps it that way.
// Dots are allowed for dotted identifiers such as alert kinds (`payment.review_needed`), hyphens for `cc-by`.
const SAFE_LITERAL = /^[a-z][a-z0-9_.-]*$/;

function literals(values: readonly string[]): string {
  return values
    .map((value) => {
      if (!SAFE_LITERAL.test(value)) {
        throw new Error(`Unsafe CHECK literal: ${value}`);
      }
      return `'${value}'`;
    })
    .join(", ");
}

/**
 * `column IN (...)` for a CHECK built from the same const tuple that types the column in
 * TypeScript, so the union type and the database constraint cannot drift apart.
 */
export function inList(column: AnyColumn, values: readonly string[]): SQL {
  return sql`${column} in (${sql.raw(literals(values))})`;
}

/** `array_column <@ ARRAY[...]`: every element of a text[] column belongs to the closed set. */
export function arrayWithin(column: AnyColumn, values: readonly string[]): SQL {
  return sql`${column} <@ ARRAY[${sql.raw(literals(values))}]::text[]`;
}

/**
 * `column ~ 'pattern'` for CHECK constraints. Patterns are our own constants and must not contain a
 * single quote or a backslash (use `[+]` rather than `\+`), which keeps the inlined literal safe.
 */
export function matches(column: AnyColumn, pattern: string): SQL {
  if (/['\\]/.test(pattern)) {
    throw new Error(`Unsafe CHECK pattern: ${pattern}`);
  }
  return sql`${column} ~ ${sql.raw(`'${pattern}'`)}`;
}
